
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_chachiyo_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_chachiyo", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.319665255844536e+00, -4.237837717946386e+00, -4.123267936116008e+00, -3.964750220348601e+00, -3.749150402928807e+00, -3.463051503937442e+00, -3.096605499352560e+00, -2.650440729937823e+00, -2.144735640914758e+00, -1.621574676611119e+00, -1.108266870335482e+00, -7.121442975674060e-01, -6.039790483246898e-01, -5.033897163807398e-01, -3.726346360117466e-01, -2.514483156936155e-01, -1.678119342812484e-01, -1.188599089015218e-01, -8.426233553343197e-02, -5.655378260881325e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


